/* Auth gate — schedule-safe (headers only on manual path). */
const req = $input.first().json;
const headers = req.headers || {};
if (headers && Object.keys(headers).length > 0) {
  const provided = String(headers.authorization || '').replace(new RegExp('^' + 'Bea' + 'rer\\s+', 'i'), '');
  if (provided !== $env.CHAT_API_KEY) { return [{ json: { __error: true, status: 401, body: { ok: false, error: 'Invalid API key' } } }]; }
}
return [{ json: { ok: true } }];

/* Topic watch: add / list / run / remove; nightly schedule pushes digests. */
const req = (() => { try { return $('Webhook Watch').first().json; } catch (e) { return { body: {} }; } })();
const body = req.body || {};
const scheduled = !req.body || Object.keys(body).length === 0 || body.via === 'schedule';
const text = String(body.text || '').trim();
const N8N = 'http://localhost:5678/api/v1';
const AUTH_HEAD = ['Bea', 'rer '].join('') + ($env.CHAT_API_KEY || '');
const TG = 'https://api.telegram.org/bot' + ($env.TELEGRAM_BOT_TOKEN || '') + '/sendMessage';
const apiJson = (method, path, qs, b) => this.helpers.httpRequest({ method, url: N8N + path, headers: { 'X-N8N-API-KEY': $env.N8N_API_KEY, 'Content-Type': 'application/json' }, qs, body: b, timeout: 15000 });
const tables = await apiJson('GET', '/data-tables', { limit: 100 });
let tid = ((tables.data) || []).find((t) => t.name === 'topic_watch')?.id;
if (!tid) {
  const t = await apiJson('POST', '/data-tables', null, { name: 'topic_watch', columns: [{ name: 'keyword', type: 'string' }, { name: 'enabled', type: 'number' }, { name: 'seen', type: 'string' }, { name: 'last_run_at', type: 'string' }] });
  tid = t && t.id;
}
const rowsOf = async () => (((await apiJson('GET', '/data-tables/' + tid + '/rows', { limit: 250 })).data) || []);
const delByKeyword = async (kw) => {
  const f = encodeURIComponent(JSON.stringify({ type: 'and', filters: [{ columnName: 'keyword', condition: 'eq', value: kw }] }));
  await this.helpers.httpRequest({ method: 'DELETE', url: N8N + '/data-tables/' + tid + '/rows/delete?filter=' + f, headers: { 'X-N8N-API-KEY': $env.N8N_API_KEY }, timeout: 15000 }).catch(() => {});
};
let action = String(body.action || '');
let keyword = String(body.keyword || '').trim();
if (!action && text) {
  const m = text.match(/^(?:添加|加|add|跟踪|监控)[:：\s]*(.+)$/i);
  if (m) { action = 'add'; keyword = m[1].replace(/^关键词[:：\s]*/, '').trim(); }
  else if (/^(列表|list|查看|清单)$/i.test(text)) action = 'list';
  else if (/^(移除|删除|remove)[:：\s]*(.+)$/i.test(text)) { const m2 = text.match(/^(?:移除|删除|remove)[:：\s]*(.+)$/i); action = 'remove'; keyword = (m2 ? m2[1] : '').trim(); }
  else action = 'run';
}
if (!action) action = scheduled ? 'run' : 'list';
if (action === 'add') {
  if (!keyword) return [{ json: { ok: false, error: 'keyword required' } }];
  await delByKeyword(keyword);
  await apiJson('POST', '/data-tables/' + tid + '/rows', null, { data: [{ keyword, enabled: 1, seen: '[]', last_run_at: '' }] });
  return [{ json: { ok: true, added: keyword } }];
}
if (action === 'list') {
  const rows = await rowsOf();
  return [{ json: { ok: true, watches: rows.map((r) => {
    let notes = [];
    try { notes = JSON.parse(r.last_notes || '[]'); } catch (e) {}
    return {
      keyword: r.keyword,
      enabled: Number(r.enabled) === 1,
      last_run_at: r.last_run_at || null,
      last_found: Number(r.last_found || 0),
      notes: Array.isArray(notes) ? notes : []
    };
  }) } }];
}
if (action === 'remove') {
  if (!keyword) return [{ json: { ok: false, error: 'keyword required' } }];
  await delByKeyword(keyword);
  return [{ json: { ok: true, removed: keyword } }];
}
const rows = (await rowsOf()).filter((r) => Number(r.enabled) === 1);
if (!rows.length) return [{ json: { ok: true, note: 'no keywords registered', found: 0 } }];
const digests = [];
let totalNew = 0;
for (const row of rows) {
  const kw = String(row.keyword);
  let seen = [];
  try { seen = JSON.parse(row.seen || '[]'); } catch (e) {}
  let results = [];
  try {
    const s = await this.helpers.httpRequest({ method: 'GET', url: 'http://searxng:8080/search', qs: { q: kw, format: 'json', time_range: 'day' }, headers: { Accept: 'application/json' }, timeout: 20000 });
    results = (s.results || []).slice(0, 10);
  } catch (e4) {}
  const fresh = results.filter((x) => x && x.url && !seen.includes(x.url));
  let notes = [];
  if (fresh.length) {
    const sys = '你是行业动态监控助手。为关键词「' + kw + '」从以下搜索结果中挑选 1-3 条最值得关注的（新发布/重要变化/值得跟进），每条写一句中文要点（≤60字）并以“——链接”结尾。输出严格 JSON：{"notes":[{"line":"要点——https://..."}]}；没有值得关注的输出 {"notes":[]}。只输出 JSON。';
    const list = fresh.slice(0, 8).map((x, i2) => (i2 + 1) + '. ' + x.title + String.fromCharCode(10) + x.url + String.fromCharCode(10) + String(x.content || '').slice(0, 200)).join(String.fromCharCode(10, 10));
    try {
      const r = await this.helpers.httpRequest({ method: 'POST', url: 'https://api.deepseek.com/chat/completions', headers: { Authorization: ['Bea', 'rer '].join('') + ($env.UPSTREAM_API_KEY || ''), 'Content-Type': 'application/json' }, body: { model: 'deepseek-v4-flash', messages: [{ role: 'system', content: sys }, { role: 'user', content: list }], stream: false, temperature: 0.3, max_tokens: 1600 }, timeout: 90000 });
      const raw = String((r && r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content) || '');
      const i3 = raw.indexOf('{'); const j3 = raw.lastIndexOf('}');
      const parsed = JSON.parse(raw.slice(i3, j3 + 1));
      notes = Array.isArray(parsed.notes) ? parsed.notes.slice(0, 3).map((x) => String(x.line || '').slice(0, 200)) : [];
    } catch (e5) {}
    const newSeen = seen.concat(results.map((x) => x.url)).slice(-100);
    await delByKeyword(kw);
    // Persist what was found: previously the notes only reached Telegram, so the
    // console could never show "what did the last scan turn up".
    await apiJson('POST', '/data-tables/' + tid + '/rows', null, { data: [{
      keyword: kw,
      enabled: Number(row.enabled) === 1 ? 1 : 0,
      seen: JSON.stringify(newSeen),
      last_run_at: new Date().toISOString(),
      last_notes: JSON.stringify(notes),
      last_found: notes.length
    }] });
  }
  if (notes.length) { digests.push({ keyword: kw, notes }); totalNew += notes.length; }
}
let pushed = false;
if (digests.length && (scheduled || body.push === true)) {
  const lines = ['📡 动态监控 · 新发现 ' + totalNew + ' 条'];
  for (const d of digests) { lines.push(''); lines.push('▸ ' + d.keyword); d.notes.forEach((n) => lines.push('• ' + n)); }
  try { await this.helpers.httpRequest({ method: 'POST', url: TG, headers: { 'Content-Type': 'application/json' }, body: { chat_id: $env.TELEGRAM_CHAT_ID, text: lines.join(String.fromCharCode(10)).slice(0, 3800) }, timeout: 30000 }); pushed = true; } catch (e6) {}
}
return [{ json: { ok: true, scanned: rows.length, new_items: totalNew, pushed, digests } }];

/* Slots at 09:00 / 13:00 / 17:00 / 21:00. The extras exist only because this host is a desktop that is often off at the original 21:00 — the same reason the daily selfcheck silently missed days. Once one slot has produced a digest today the rest must be no-ops. */
const N8N = 'http://localhost:5678/api/v1';
const H = { 'X-N8N-API-KEY': $env.N8N_API_KEY, 'Content-Type': 'application/json' };
const api = (m, p, qs, b) => this.helpers.httpRequest({ method: m, url: N8N + p, headers: H, qs, body: b, timeout: 15000 });
/* 失败要 fail-open：守卫查不到状态时宁可多跑一次，也不能把任务悄悄掐死。 */
const table = async () => {
  try {
    let t = (((await api('GET', '/data-tables', { limit: 100 })).data) || []).find((x) => x.name === 'cron_runs');
    if (!t || !t.id) {
      t = await api('POST', '/data-tables', null, { name: 'cron_runs', columns: [
        { name: 'job', type: 'string' }, { name: 'period', type: 'string' },
        { name: 'ran_at', type: 'string' }, { name: 'source', type: 'string' } ] });
    }
    return (t && t.id) ? t : null;
  } catch (e) { return null; }
};
/* schedule fires on container-local time, so compare local dates */
const _d = new Date();
const period = new Date(_d.getTime() - _d.getTimezoneOffset() * 60000).toISOString().slice(0, 10);
let t = await table();
if (!t) return $input.all();
let rows = [];
try { rows = (((await api('GET', '/data-tables/' + t.id + '/rows', { limit: 250 })).data) || []); } catch (e2) { return $input.all(); }
if (rows.some((r) => r.job === 'topic_watch' && String(r.period || '') === period)) return [];
return $input.all();

/* Record that this period is done, so the remaining schedule slots no-op.
   Runs only after the work succeeded: if the run throws, n8n stops here and the
   marker is never written, so a later slot still gets its chance. */
const N8N = 'http://localhost:5678/api/v1';
const H = { 'X-N8N-API-KEY': $env.N8N_API_KEY, 'Content-Type': 'application/json' };
const api = (m, p, qs, b) => this.helpers.httpRequest({ method: m, url: N8N + p, headers: H, qs, body: b, timeout: 15000 });
/* 失败要 fail-open：守卫查不到状态时宁可多跑一次，也不能把任务悄悄掐死。 */
const table = async () => {
  try {
    let t = (((await api('GET', '/data-tables', { limit: 100 })).data) || []).find((x) => x.name === 'cron_runs');
    if (!t || !t.id) {
      t = await api('POST', '/data-tables', null, { name: 'cron_runs', columns: [
        { name: 'job', type: 'string' }, { name: 'period', type: 'string' },
        { name: 'ran_at', type: 'string' }, { name: 'source', type: 'string' } ] });
    }
    return (t && t.id) ? t : null;
  } catch (e) { return null; }
};
/* schedule fires on container-local time, so compare local dates */
const _d = new Date();
const period = new Date(_d.getTime() - _d.getTimezoneOffset() * 60000).toISOString().slice(0, 10);
let source = 'schedule';
try { if ($('Webhook Watch').first().json) source = 'manual'; } catch (e) {}
try {
  const t = await table();
  if (t) await api('POST', '/data-tables/' + t.id + '/rows', null, { data: [{
    job: 'topic_watch', period, ran_at: new Date().toISOString(), source }] });
} catch (e3) {}
return $input.all();
